def get_values_by_priority(d, keys):
    """
    Returns a list of values from the dictionary 'd' corresponding to the keys in 'keys' order.
    If a key is not found, it is ignored. If a value is a list, all its elements are included.
    If a value is a single element, it is added to the result list.

    :param d: Dictionary with string keys and values that can be either single values or lists.
    :param keys: List of keys in order of priority.
    :return: List of values corresponding to the keys in the specified order.
    """
    def helper(index):
        if index == len(keys):
            return []
        key = keys[index]
        value = d.get(key)
        if isinstance(value, list):
            return value + helper(index + 1)
        elif value is not None:
            return [value] + helper(index + 1)
        else:
            return helper(index + 1)

    return helper(0)
