def find_cheapest_cars(data, location):
    """
    Returns a list of dictionaries representing the cheapest cars sold by unique sellers in the specified location.

    :param data: List of dictionaries, each containing car sale information.
    :param location: String representing the location to filter car sales.
    :return: List of dictionaries, each representing the cheapest car sold by a unique seller in the specified location.
    """
    cheapest_cars = {}

    for car in data:
        if car['location'] == location:
            if car['seller'] in cheapest_cars:
                if car['price'] < cheapest_cars[car['seller']]['price']:
                    cheapest_cars[car['seller']] = car
            else:
                cheapest_cars[car['seller']] = car

    return list(cheapest_cars.values())
