class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """
        Insert a value into the binary search tree. If the value already exists,
        insert it as the left child of the parent node.
        """
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        if value == node.value:
            if node.left:
                self._insert_recursively(node.left, value)
            else:
                node.left = TreeNode(value)
        elif value < node.value:
            if node.left:
                self._insert_recursively(node.left, value)
            else:
                node.left = TreeNode(value)
        else:
            if node.right:
                self._insert_recursively(node.right, value)
            else:
                node.right = TreeNode(value)

    def search(self, value):
        """
        Return True if the value exists in the binary search tree, otherwise return False.
        """
        return self._search_recursively(self.root, value)

    def _search_recursively(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        elif value < node.value:
            return self._search_recursively(node.left, value)
        else:
            return self._search_recursively(node.right, value)

    def in_order_traversal(self):
        """
        Return a list of values in the binary search tree in ascending order.
        """
        return self._in_order_traversal(self.root)

    def _in_order_traversal(self, node):
        if node is None:
            return []
        return self._in_order_traversal(node.left) + [node.value] + self._in_order_traversal(node.right)
