def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list of numbers.

    :param numbers: List of integers
    :return: Tuple (max_val, min_val)
    :raises ValueError: If the input list is empty
    """
    if not numbers:
        raise ValueError("The input list should not be empty.")
    max_val = numbers[0]
    min_val = numbers[0]
    for number in numbers:
        if number > max_val:
            max_val = number
        if number < min_val:
            min_val = number
