def remove_duplicate_values(input_dict):
    """
    Removes duplicate values from the input dictionary, preserving the order of the first occurrence of each unique value.

    :param input_dict: A dictionary with string keys and integer values.
    :return: A dictionary with duplicate values removed.
    """
    seen = set()
    result = {}
    for key, value in input_dict.items():
        if value not in seen:
            seen.add(value)
            result[key] = value
    return result

