def search(nums, target):
    """
    Searches for the target in a rotated sorted array and returns its index.
    If the target is not found, returns -1.

    :param nums: List[int] - A rotated sorted array of distinct integers.
    :param target: int - The target integer to search for.
    :return: int - The index of the target if found, otherwise -1.
    """
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:
            if nums[left] <= target <= nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] <= target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1
```

