class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        Ensures all rows have the same length.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("All rows must be lists of the same length.")
        self.data = data

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must be of the same size for addition.")
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(len(self.data[0]))] for i in range(len(self.data))])

    def __sub__(self, other):
        """
        Subtracts two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must be of the same size for subtraction.")
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(len(self.data[0]))] for i in range(len(self.data))])

    def __mul__(self, other):
        """
        Multiplies the matrix by a scalar or another matrix.
        If multiplying by another matrix, ensures the number of columns in the first matrix equals the number of rows in the second matrix.
        """
        if isinstance(other, (int, float)):
            return Matrix([[self.data[i][j] * other for j in range(len(self.data[0]))] for i in range(len(self.data))])
        elif isinstance(other, Matrix):
            if len(self.data[0]) != len(other.data):
                raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix for multiplication.")
            return Matrix([[sum(self.data[i][k] * other.data[k][j] for k in range(len(self.data[0]))) for j in range(len(other.data[0]))] for i in range(len(self.data))])
        else:
            raise ValueError("Multiplication is only defined between a matrix and a scalar or another matrix.")

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        return Matrix([[self.data[row][col] for row in range(len(self.data))] for col in range(len(self.data[0]))])

    def shape(self):
        """
        Returns a tuple representing the dimensions of the matrix.
        """
        return (len(self.data), len(self.data[0]))
