class BankAccount:
    def __init__(self, balance=0):
        """
        Initialize the bank account with a given balance.
        If the balance is negative, set it to 0 and print an error message.
        """
        if balance >= 0:
            self.balance = balance
        else:
            print("Initial balance cannot be negative. Setting balance to 0.")
            self.balance = 0

    def deposit(self, amount):
        """
        Add the specified amount to the balance if the amount is positive.
        Print an error message if the amount is zero or negative.
        """
        if amount > 0:
            self.balance += amount
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        """
        Subtract the specified amount from the balance if the amount is positive and the balance is sufficient.
        Print an error message if the amount is zero or negative, or if the balance is insufficient.
        """
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
            else:
                print("Insufficient balance for withdrawal.")
        else:
            print("Withdrawal amount must be positive.")

    def get_balance(self):
        """
        Return the current balance of the account.
        """
        return self.balance
