class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given data.
        Raises ValueError if the input data does not form a valid matrix.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Invalid matrix data: Each row must have the same number of columns.")
        self.data = [row[:] for row in data]  # Deep copy to avoid issues with mutable default arguments
        self.rows = len(data)
        self.cols = len(data[0]) if data else 0

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        Raises ValueError if the dimensions do not match.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def __sub__(self, other):
        """
        Subtracts one matrix from another, both of the same dimensions.
        Raises ValueError if the dimensions do not match.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted.")
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def __mul__(self, other):
        """
        Multiplies the matrix by another matrix or a scalar.
        Raises ValueError if the matrices have incompatible dimensions for multiplication.
        Raises TypeError if the multiplication is attempted with an unsupported type.
        """
        if isinstance(other, (int, float)):
            # Scalar multiplication
            return Matrix([[self.data[i][j] * other for j in range(self.cols)] for i in range(self.rows)])
        elif isinstance(other, Matrix):
            # Matrix multiplication
            if self.cols != other.rows:
                raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix.")
            result = [[sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)] for i in range(self.rows)]
            return Matrix(result)

        raise TypeError("Can only multiply a matrix with another matrix or scalar.")

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
