def factorial(n):
    """
    Calculate the factorial of a non-negative integer n.

    Args:
    n (int): The integer for which the factorial is to be calculated.

    Returns:
    int: The factorial of the integer n.

    Raises:
    ValueError: If n is a negative integer.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    elif n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

import unittest

class TestFactorial(unittest.TestCase):
    def test_factorial_of_zero(self):
        self.assertEqual(factorial(0), 1)

    def test_factorial_of_positive_integer(self):
        self.assertEqual(factorial(5), 120)
        self.assertEqual(factorial(10), 3628800)

    def test_factorial_of_large_number(self):
        self.assertEqual(factorial(20), 2432902008176640000)

    def test_factorial_of_negative_number(self):
        with self.assertRaises(ValueError) as context:
            factorial(-1)
        self.assertEqual(str(context.exception), "Factorial is not defined for negative numbers")

    def test_factorial_of_one(self):
        self.assertEqual(factorial(1), 1)

if __name__ == '__main__':
    unittest.main()
