def generate_report(sales_data):
    """
    Generates a summary report from sales data.

    Parameters:
    sales_data (list of dict): A list of dictionaries, each containing 'product_id', 'quantity', and 'price'.

    Returns:
    str: A formatted summary report string.
    """
    report_data = {}

    for entry in sales_data:
        product_id = entry['product_id']
        quantity = entry['quantity']
        price = entry['price']

        if product_id not in report_data:
            report_data[product_id] = {'total_quantity': 0, 'total_revenue': 0}

        report_data[product_id]['total_quantity'] += quantity
        report_data[product_id]['total_revenue'] += quantity * price

    report = ""
    for product_id, data in report_data.items():
        report += f"Product ID: {product_id}, Total Quantity Sold: {data['total_quantity']}, Total Revenue: {data['total_revenue']}\n"

    return report.strip()
