def flatten(lst):
    """Recursively flattens a nested list."""
    for item in lst:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

def variables_to_dict(variable_names, args):
    """
    Constructs a dictionary mapping variable names to their corresponding values
    from the arguments dictionary. Named arguments take precedence over unnamed
    arguments, which are accessed in order from the list under the key '_'.
    If a variable name is not found, it is assigned an empty string.
    """
    result = {}
    unnamed_idx = 0
    flat_names = list(flatten(variable_names))

    for var_name in flat_names:
        if var_name in args:
            result[var_name] = args[var_name]
        elif unnamed_idx < len(args.get('_', [])):
            result[var_name] = args['_'][unnamed_idx]
            unnamed_idx += 1
        else:
            result[var_name] = ''

    return result
```

