def is_balanced(expression):
    """
    Checks if the given expression containing parentheses, curly brackets, and square brackets is balanced.

    :param expression: A string containing the expression to be checked.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack
