def remove_file_extension(file_name, allowed_extensions):
    """
    Removes the file extension from the file name if the extension is in the allowed list.

    Parameters:
    - file_name (str): The file name.
    - allowed_extensions (list of str): The list of allowed file extensions.

    Returns:
    - str: The file name without the extension if the extension is allowed; otherwise, the original file name.
    """
    last_dot_position = None

    for i in range(len(file_name) - 1, -1, -1):
        if file_name[i] == '.':
            last_dot_position = i
            break

    if last_dot_position is None or last_dot_position == 0:
        return file_name

    extension = ''
    for i in range(last_dot_position + 1, len(file_name)):
        extension += file_name[i]

    for allowed_extension in allowed_extensions:
        if len(extension) == len(allowed_extension):
            match = True
            for j in range(len(extension)):
                if extension[j] != allowed_extension[j]:
                    match = False
                    break
            if match:
                return file_name[:last_dot_position]

    return file_name
