class TemperatureConverter:
    def to_fahrenheit(self, value, source_unit):
        """
        Convert the given temperature value to Fahrenheit.

        :param value: The temperature value to convert.
        :param source_unit: The unit of the source temperature ("fahrenheit", "celsius", or "kelvin").
        :return: The converted temperature in Fahrenheit or an error message if the source unit is invalid.
        """
        if source_unit.lower() == "fahrenheit":
            return value
        elif source_unit.lower() == "celsius":
            return (value * 9/5) + 32
        elif source_unit.lower() == "kelvin":
            return (value - 273.15) * 9/5 + 32
        else:
            return "Invalid source unit"

    def to_celsius(self, value, source_unit):
        """
        Convert the given temperature value to Celsius.

        :param value: The temperature value to convert.
        :param source_unit: The unit of the source temperature ("fahrenheit", "celsius", or "kelvin").
        :return: The converted temperature in Celsius or an error message if the source unit is invalid.
        """
        if source_unit.lower() == "celsius":
            return value
        elif source_unit.lower() == "fahrenheit":
            return (value - 32) * 5/9
        elif source_unit.lower() == "kelvin":
            return value - 273.15
        else:
            return "Invalid source unit"

    def to_kelvin(self, value, source_unit):
        """
        Convert the given temperature value to Kelvin.

        :param value: The temperature value to convert.
        :param source_unit: The unit of the source temperature ("fahrenheit", "celsius", or "kelvin").
        :return: The converted temperature in Kelvin or an error message if the source unit is invalid.
        """
        if source_unit.lower() == "kelvin":
            return value
        elif source_unit.lower() == "celsius":
            return value + 273.15
        elif source_unit.lower() == "fahrenheit":
            return (value - 32) * 5/9 + 273.15
        else:
            return "Invalid source unit"
