def best_three_distinct_scores(scores):
    """
    Returns the top three distinct scores in descending order from the given list of scores.

    :param scores: List[int] - A list of integers representing the scores.
    :return: List[int] - A list of the top three distinct scores in descending order.
    """
    def custom_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if arr[j] < arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr

    distinct_scores = []
    for score in scores:
        if score not in distinct_scores:
            distinct_scores.append(score)

    sorted_scores = custom_sort(distinct_scores)

    return sorted_scores[:3]
