def convert_number_to_words(number):
    """
    Convert a positive integer to its English word representation.

    Parameters:
    number (int): A positive integer between 1 and 99999 inclusive.

    Returns:
    str: The English word representation of the number with each word capitalized and separated by a single space.

    Raises:
    ValueError: If the number is not within the range 1 to 99999.
    """
    if not (1 <= number <= 99999):
        raise ValueError("Number out of range. It should be between 1 and 99999 inclusive.")

    ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"]
    teens = ["Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
    tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

    def two_digit_number_to_words(n):
        if n < 10:
            return ones[n]
        elif 10 <= n < 20:
            return teens[n - 10]
        else:
            ten_part = tens[n // 10]
            one_part = ones[n % 10]
            return ten_part + ('' if one_part == "" else ' ' + one_part)

    def three_digit_number_to_words(n):
        hundred_part = ones[n // 100] + ' Hundred' if n // 100 > 0 else ''
        remaining_part = two_digit_number_to_words(n % 100)
        if hundred_part and remaining_part:
            return hundred_part + ' ' + remaining_part
        return hundred_part or remaining_part

    words = []
    if number >= 1000:
        thousands_part = three_digit_number_to_words(number // 1000) + ' Thousand'
        words.append(thousands_part)

    remaining_part = number % 1000
    if remaining_part > 0:
        words.append(three_digit_number_to_words(remaining_part))

    return ' '.join(words)
