def generate_report(inventory_json):
    """
    Generates a summary report of the bookstore's inventory.

    Parameters:
    inventory_json (dict): A dictionary representing the bookstore's inventory.

    Returns:
    dict: A dictionary containing the total number of books in stock, total value of the inventory,
          number of books by each author, and average price of books by each publisher.
    """
    inventory = inventory_json.get('books', [])
    total_books = 0
    total_value = 0.0
    author_count = {}
    publisher_prices = {}

    for book in inventory:
        total_books += book['quantity']
        total_value += book['quantity'] * book['price']

        author = book['author']
        author_count[author] = author_count.get(author, 0) + 1

        publisher = book['publisher']
        if publisher in publisher_prices:
            publisher_prices[publisher]['total_price'] += book['price'] * book['quantity']
            publisher_prices[publisher]['total_quantity'] += book['quantity']
        else:
            publisher_prices[publisher] = {
                'total_price': book['price'] * book['quantity'],
                'total_quantity': book['quantity']
            }

    average_publisher_price = {
        publisher: info['total_price'] / info['total_quantity'] for publisher, info in publisher_prices.items()
    }

    return {
        'total_books_in_stock': total_books,
        'total_value_of_inventory': total_value,
        'number_of_books_by_each_author': author_count,
        'average_price_of_books_by_each_publisher': average_publisher_price
