def nested_product(nested_list):
    """
    Calculate the product of all numbers in a nested list.

    :param nested_list: A nested list of integers and floating-point numbers.
    :return: A floating-point number representing the product of all numbers.
    """
    def _product(lst):
        product = 1.0
        for item in lst:
            if isinstance(item, list):
                product *= _product(item)
            elif isinstance(item, (int, float)):
                product *= item
        return product

