import sqlite3
from sqlite3 import Error

def create_connection(db_file):
    """Create a database connection to the SQLite database specified by db_file."""
    conn = None
    try:
        conn = sqlite3.connect(db_file)
    except Error as e:
        print(f"Error connecting to database: {e}")
    return conn

def create_table(conn, create_table_sql):
    """Create a table from the create_table_sql statement."""
    try:
        c = conn.cursor()
        c.execute(create_table_sql)
    except Error as e:
        print(f"Error creating table: {e}")

def insert_row(conn, table_name, data):
    """Insert a new row into the table."""
    placeholders = ','.join(['?'] * len(data))
    sql = f'INSERT INTO {table_name} VALUES ({placeholders})'
    cur = conn.cursor()
    try:
        cur.execute(sql, data)
        conn.commit()
    except Error as e:
        print(f"Error inserting data: {e}")

def CSV_to_db(csv_file_path, db_file, table_name):
    """Convert CSV file to SQLite db."""
    conn = create_connection(db_file)

    if conn is not None:
        try:
            with open(csv_file_path, newline='') as csvfile:
                reader = csv.reader(csvfile)
                columns = next(reader)  # first row must be column headers
                create_table_sql = f'CREATE TABLE IF NOT EXISTS {table_name} ({", ".join([f"{col} TEXT" for col in columns])})'
                create_table(conn, create_table_sql)

                for row in reader:
                    insert_row(conn, table_name, tuple(row))

        except FileNotFoundError:
            print(f"The file {csv_file_path} does not exist.")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            if conn:
                conn.close()
    else:
        print("Error! Cannot create the database connection.")
