def calculate_power(base=3, exponent=4):
    """
    Calculate the power of a given base raised to an exponent using recursion.

    Parameters:
    base (int or float): The base number.
    exponent (int): The exponent to which the base is raised.

    Returns:
    int or float: The result of base raised to the power of exponent.
    """
    if exponent == 0:
