def validate_brackets(expression: str) -> bool:
    """
    Checks if the given string contains balanced brackets.

    :param expression: A string containing characters '(', ')', '{', '}', '[', and ']'.
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False

