def detect_cycle(graph):
    """
    Detects if there is a cycle in a directed graph represented as an adjacency list.

    :param graph: A dictionary representing the graph where each key is a vertex and its value is a list of adjacent vertices.
    :return: True if the graph contains a cycle, False otherwise.
    """
    def dfs(node, visited, recursion_stack):
        visited[node] = True
        recursion_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, recursion_stack):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    V = len(graph)
    visited = [False] * V
    recursion_stack = [False] * V

    for node in range(V):
        if not visited[node]:
            if dfs(node, visited, recursion_stack):
                return True
    return False
