def is_float_type(node):
    """
    Determines if the given AST node represents a float or double type.

    :param node: A node from an Abstract Syntax Tree (AST).
    :return: True if the node represents a float or double type, False otherwise.
    """
    if hasattr(node, 'metadata') and isinstance(node.metadata, dict):
        precision = node.metadata.get('precision')
        if precision in ('single', 'double'):
            return True

    if hasattr(node, 'str') and isinstance(node.str, str):
        if '.' in node.str or 'f' in node.str.lower() or 'e' in node.str.lower():
            return True

    if hasattr(node, 'astOperand1') and hasattr(node, 'astOperand2'):
        if is_float_type(node.astOperand1) or is_float_type(node.astOperand2):
            return True

    if hasattr(node, 'typeStartToken') and hasattr(node, 'typeEndToken'):
        typeStartToken = getattr(node, 'typeStartToken', '')
        typeEndToken = getattr(node, 'typeEndToken', '')
        if typeStartToken in ('float', 'double') or typeEndToken in ('float', 'double'):
            return True

    return False
