def validate_conditional_statement(line):
    """
    Validates whether the given line is a valid conditional statement.

    Parameters:
    line (str): The line of code to validate.

    Returns:
    bool: True if the line is a valid conditional statement, False otherwise.
    """
    line = line.strip()
    if not line.startswith("if "):
        return False

    condition_start = len("if ")
    if line[condition_start] != '(':
        return False

    open_parentheses = 0
    condition_end = None
    for i, char in enumerate(line[condition_start:], start=condition_start):
        if char == '(':
            open_parentheses += 1
        elif char == ')':
            open_parentheses -= 1
            if open_parentheses == 0:
                condition_end = i
                break

    if condition_end is None:
        return False

    if not line.endswith(':'):
        return False

    if line[condition_end + 1:].strip() != ':':
        return False

    return True
