def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit up to which prime numbers are summed.
    :return: The sum of all prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return sum(index for index, prime in enumerate(is_prime) if prime)
