class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with given data.

        :param data: List of lists representing the matrix.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Add two matrices.

        :param other: Another Matrix instance.
        :return: New Matrix instance representing the sum.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtract two matrices.

        :param other: Another Matrix instance.
        :return: New Matrix instance representing the difference.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiply two matrices.

        :param other: Another Matrix instance.
        :return: New Matrix instance representing the product.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix to multiply.")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def display(self):
        """
        Print the matrix in a formatted way.
        """
        for row in self.data:
            print(" ".join(map(str, row)))
