import json

def print_json(data, indent_level=0):
    """
    Recursively prints the data in a formatted JSON-like way.

    :param data: The data to print, which can be a dictionary, list, tuple, or a basic data type.
    :param indent_level: The current level of indentation for nested structures.
    """
    indent = ' ' * indent_level * 2
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, (dict, list, tuple)):
                print(f"{indent}{key}:")
                print_json(value, indent_level + 1)
            else:
                print(f"{indent}{key}: {value}")
    elif isinstance(data, (list, tuple)):
        print(f"{indent}[")
        for item in data:
            if isinstance(item, (dict, list, tuple)):
                print_json(item, indent_level + 1)
            else:
                print(f"{' ' * (indent_level + 1) * 2}{item},")
        print(f"{indent}]")
    else:
        print(f"{indent}{data}")

