def recursive_binary_search(numbers, target):
    """
    Perform a recursive binary search on a sorted array to find the index of the target.

    Parameters:
    numbers (list of int): The sorted array of integers.
    target (int): The target integer to search for.

    Returns:
    int: The index of the target integer in the array, or -1 if not found.
    """
    def binary_search_helper(numbers, target, low, high):
        print(f"Searching for {target} in {numbers[low:high+1]}")

        if low > high:
            return -1

        mid = (low + high) // 2

        if numbers[mid] == target:
            return mid
        elif numbers[mid] < target:
            return binary_search_helper(numbers, target, mid + 1, high)
        else:
            return binary_search_helper(numbers, target, low, mid - 1)

    return binary_search_helper(numbers, target, 0, len(numbers) - 1)

