def get_stronger_lower_bound(list_a, list_b):
    """
    Returns a list containing the stronger lower bound for each pair of elements from list_a and list_b.

    Parameters:
    list_a (List[Union[int, float, str, None]]): The first list of potential lower bounds.
    list_b (List[Union[int, float, str, None]]): The second list of potential lower bounds.

    Returns:
    List[Union[float, None]]: A list of stronger lower bounds.
    """
    def parse_value(value):
        if isinstance(value, (int, float)):
            return float(value)
        if value is None:
            return None
        try:
            return float(value)
        except ValueError:
            return None

    result = []
    for a, b in zip(list_a, list_b):
        a = parse_value(a)
        b = parse_value(b)
        if a is None and b is None:
            result.append(None)
        elif a is None:
            result.append(b)
        elif b is None:
            result.append(a)
        else:
            result.append(max(a, b))
    return result

