import math

def calculate_area(shape):
    """
    Calculate the area of a shape based on the provided dictionary.

    Args:
    shape (dict): A dictionary with keys 'type' and 'dimensions'.
                  'type' can be 'circle' or 'rectangle'.
                  'dimensions' is a dictionary with necessary dimensions for the shape.

    Returns:
    float: The area of the shape.

    Raises:
    ValueError: If the input dictionary is missing required keys or contains unsupported shape types.
    """
    if shape['type'] == 'circle':
        radius = shape['dimensions'].get('radius')
        if radius is not None:
            return math.pi * (radius ** 2)
        else:
            raise ValueError("Missing or invalid 'radius' for circle.")
    elif shape['type'] == 'rectangle':
        width = shape['dimensions'].get('width')
        height = shape['dimensions'].get('height')
        if width is not None and height is not None:
            return width * height
        else:
            raise ValueError("Missing or invalid 'width' or 'height' for rectangle.")
    else:
        raise ValueError("Unsupported shape type.")
