class TreeNode:
    def __init__(self, value):
        """Initialize a tree node with a given value."""
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        """Initialize an empty binary search tree."""
        self.root = None

    def insert(self, value):
        """Inserts a new value into the BST."""
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert recursively."""
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def delete(self, value):
        """Deletes a value from the BST."""
        self.root = self._delete_recursively(self.root, value)

    def _delete_recursively(self, node, value):
        """Helper method to delete recursively."""
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_recursively(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursively(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            node.value = self._min_value_node(node.right).value
            node.right = self._delete_recursively(node.right, node.value)
        return node

    def _min_value_node(self, node):
        """Returns the node with the minimum value in BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        """Returns a list of values in the BST in in-order traversal order."""
        values = []
        self._inorder_recursively(self.root, values)
        return values

    def _inorder_recursively(self, node, values):
        """Helper method to perform in-order traversal recursively."""
        if node is not None:
            self._inorder_recursively(node.left, values)
            values.append(node.value)
            self._inorder_recursively(node.right, values)
