def flattenDictionary(nested_dict, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with keys in dot notation.

    :param nested_dict: The nested dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys (default is '.').
    :return: A flattened dictionary with dot notation keys.
    """
    items = []
    for k, v in nested_dict.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flattenDictionary(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

