def find_largest_prime_below(n):
    """
    Find the largest prime number less than n using a sieve algorithm.

    Parameters:
    n (int): The upper limit to find the largest prime below.

    Returns:
    int or None: The largest prime number less than n, or None if no such prime exists.
    """
    if n <= 2:
        return None  # No prime numbers less than 2

    sieve = [True] * n
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n, start):
                sieve[multiple] = False

    for num in range(n-1, 1, -1):
        if sieve[num]:
            return num

    return None  # Should not reach here if n > 2
