def sieve_of_eratosthenes(limit):
    """Generate a list of prime numbers up to a given limit using the Sieve of Eratosthenes algorithm."""
    is_prime = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, limit + 1) if is_prime[p]]


def count_distinct_prime_factors(n):
    """Return the number of distinct prime factors of the integer n."""
    if n <= 1:
        return 0

    limit = int(n**0.5) + 1
    prime_numbers = sieve_of_eratosthenes(limit)

    distinct_prime_factors_count = 0

    for prime in prime_numbers:
        if prime * prime > n:
            break
        if n % prime == 0:
            distinct_prime_factors_count += 1
            while n % prime == 0:
                n //= prime
    if n > 1:
        distinct_prime_factors_count += 1

    return distinct_prime_factors_count

# Example usage
print(count_distinct_prime_factors(60))  # Output: 3
