class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        """
        Inserts a new node with the given data at the end of the list.
        """
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def delete(self, key):
        """
        Deletes the first node with the given key from the list.
        Returns True if the node was found and deleted, otherwise returns False.
        """
        current = self.head
        previous = None
        while current:
            if current.data == key:
                if previous:
                    previous.next = current.next
                else:
                    self.head = current.next
                return True
            previous = current
            current = current.next
        return False

    def traverse(self):
        """
        Prints the elements of the list in order, separated by " -> ", and ending with "None".
        """
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")
