def count_elements(start, stop, step):
    """
    Returns the number of elements in the sequence generated by range(start, stop, step).

    Parameters:
    start (int): The starting value of the sequence.
    stop (int): The stopping value of the sequence (exclusive).
    step (int): The step value between each element in the sequence.

    Returns:
    int: The number of elements in the sequence.

    Raises:
    ValueError: If step is zero.
    """
    if step == 0:
        raise ValueError("step cannot be zero.")
    elif step > 0:
        return max(0, (stop - start + step - 1) // step)
    else:
        return max(0, (stop - start + step + 1) // step)
