def merge_unique_integers(list_1, list_2):
    """
    Merges two lists of integers into a single list without duplicates.

    Parameters:
    list_1 (list of int or None): The first list of integers.
    list_2 (list of int or None): The second list of integers.

    Returns:
    list of int or None: The merged list of unique integers or None if both inputs are None.
    """
    if list_1 is None and list_2 is None:
        return None
    if list_1 is None:
        return list_2
    if list_2 is None:
        return list_1

    merged_list = []
    for num in list_1:
        is_duplicate = False
        for existing_num in merged_list:
            if num == existing_num:
                is_duplicate = True
                break
        if not is_duplicate:
            merged_list.append(num)

    for num in list_2:
        is_duplicate = False
        for existing_num in merged_list:
            if num == existing_num:
                is_duplicate = True
                break
        if not is_duplicate:
            merged_list.append(num)

    return merged_list
