    """
    Determines if two strings s and t are isomorphic.

    Args:
    s (str): The first string.
    t (str): The second string.

    Returns:
    bool: True if the strings are isomorphic, False otherwise.
    """
    mapping_s_t = {}
    mapping_t_s = {}

    for char_s, char_t in zip(s, t):
        if char_s in mapping_s_t:
            if mapping_s_t[char_s] != char_t:
                return False
        else:
            mapping_s_t[char_s] = char_t

        if char_t in mapping_t_s:
            if mapping_t_s[char_t] != char_s:
                return False
        else:
            mapping_t_s[char_t] = char_s

