def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes_below(limit):
    """Calculate the sum of all prime numbers less than the given limit."""
    total = 0
    for num in range(2, limit):
        if is_prime(num):
            total += num
    return total

