def calculate_expression(expression):
    """
    Evaluates a simple arithmetic expression given as a string.

    Parameters:
    expression (str): A string representing the arithmetic expression in the format
                      "<number1> <operator> <number2>".

    Returns:
    int or None: The result of the arithmetic operation if valid, otherwise None.
    """
    try:
        parts = expression.split()
        if len(parts) != 3:
            return None

        num1 = int(parts[0])
        num2 = int(parts[2])
        operator = parts[1]

        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
            if abs(result) > 1000:
                return None
        elif operator == '/':
            if num2 == 0:
                return None
            result = num1 // num2
            if abs(result) > 1000:
                return None
        else:
            return None

        return result

    except ValueError:
        return None
