def validate_and_sum(nested_list):
    """
    Computes the sum of all integers in a nested list.

    Parameters:
    nested_list (list): A nested list of integers or other data types.

    Returns:
    int or str: The sum of all integers in the nested list, or "Invalid input" if any non-integer values are present.
    """
    def is_integer_list(lst):
        """
        Recursively checks if all elements in the list are integers or lists of integers.

        Parameters:
        lst (list): The list to check.

        Returns:
        bool: True if all elements are integers or lists of integers, False otherwise.
        """
        for element in lst:
            if isinstance(element, int):
                continue
            elif isinstance(element, list):
                if not is_integer_list(element):
                    return False
            else:
                return False
        return True

    def sum_nested_list(lst):
        """
        Recursively sums all integers in the nested list.

        Parameters:
        lst (list): The nested list to sum.

        Returns:
        int: The sum of all integers in the nested list.
        """
        total = 0
        for element in lst:
            if isinstance(element, int):
                total += element
            elif isinstance(element, list):
                total += sum_nested_list(element)
        return total

    if is_integer_list(nested_list):
        return sum_nested_list(nested_list)
    else:
        return "Invalid input"
