def optimize_fibonacci(n, memo=None):
    """
    Calculate the nth Fibonacci number using memoization.

    Parameters:
    n (int): The index of the Fibonacci number to be calculated.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n == 1:
        return 1
    memo[n] = optimize_fibonacci(n-1, memo) + optimize_fibonacci(n-2, memo)
    return memo[n]
