class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Data must be a 2D list with consistent row lengths.")
        self.data = data

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must be of the same dimensions for addition.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(len(self.data[0]))]
            for i in range(len(self.data))
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must be of the same dimensions for subtraction.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(len(self.data[0]))]
            for i in range(len(self.data))
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices where the number of columns in the first matrix
        equals the number of rows in the second matrix.
        """
        if not isinstance(other, Matrix) or len(self.data[0]) != len(other.data):
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix for multiplication.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(len(self.data[0]))) for j in range(len(other.data[0]))]
            for i in range(len(self.data))
        ]
        return Matrix(result)

    def shape(self):
        """
        Returns a tuple representing the dimensions of the matrix.
        """
        return (len(self.data), len(self.data[0]))

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
