        return jsonify({"error": "Request must be JSON"}), 400

    data = request.get_json()

    if 'numbers' not in data or not isinstance(data['numbers'], list):
        return jsonify({"error": "Input data must be a list"}), 400

    total_sum = 0
    for item in data['numbers']:
        if not isinstance(item, int):
            return jsonify({"error": "All items in the list must be integers"}), 400
        total_sum += item

