def convert_file_sizes(file_sizes):
    """
    Convert file sizes from bytes to a human-readable format (KB, MB, GB).

    Parameters:
    file_sizes (dict): A dictionary with filenames as keys and file sizes in bytes as values.

    Returns:
    dict: A dictionary with filenames as keys and file sizes in human-readable format as values.
    """
    converted_sizes = {}
    for filename, size in file_sizes.items():
        if size < 1024:
            converted_sizes[filename] = f"{size} B"
        elif size < 1024 * 1024:
            converted_sizes[filename] = f"{size / 1024:.2f} KB"
        elif size < 1024 * 1024 * 1024:
            converted_sizes[filename] = f"{size / (1024 * 1024):.2f} MB"
        else:
            converted_sizes[filename] = f"{size / (1024 * 1024 * 1024):.2f} GB"
    return converted_sizes

