def find_substring(text, pattern):
    """
    Returns the starting index of the first occurrence of the pattern in the text.
    If the pattern is not found, returns -1.

    :param text: The string in which to search for the pattern.
    :param pattern: The string pattern to search for in the text.
    :return: The starting index of the first occurrence of the pattern, or -1 if not found.
    """
    if not pattern:
        return 0
    if len(pattern) > len(text):
        return -1

    for i in range(len(text) - len(pattern) + 1):
        match = True
        for j in range(len(pattern)):
            if text[i + j] != pattern[j]:
                match = False
                break
        if match:
            return i
    return -1
