def merge_ranges(ranges):
    """Merge overlapping ranges in a sorted list of range tuples."""
    merged = []
    if not ranges:
        return merged
    current_range = ranges[0]
    for next_range in ranges[1:]:
        if current_range[1] >= next_range[0]:  # Overlapping ranges
            current_range = (current_range[0], max(current_range[1], next_range[1]))
        else:
            merged.append(current_range)
            current_range = next_range
    merged.append(current_range)  # Add the last range
    return merged

def binary_search_ranges(ranges, target, low, high):
    """Recursive binary search on the list of merged ranges."""
    if low > high:
        return False
    mid = (low + high) // 2
    start, end = ranges[mid]
    if start <= target <= end:
        return True
    elif target < start:
        return binary_search_ranges(ranges, target, low, mid - 1)
    else:
        return binary_search_ranges(ranges, target, mid + 1, high)

def is_target_in_ranges(ranges, target):
    """Check if the target is within any of the ranges using the merged range binary search."""
    merged_ranges = merge_ranges(ranges)
    return binary_search_ranges(merged_ranges, target, 0, len(merged_ranges) - 1)
