def find_missing_number(nums):
    """
    Finds the smallest missing positive integer in the given array of integers.

    :param nums: List[int] - An array of integers.
    :return: int - The smallest missing positive integer.
    """
    # First, segregate positive numbers from non-positive numbers
    index = 0
    n = len(nums)

    while index < n:
        if nums[index] <= 0:
            nums[index], nums[n - 1] = nums[n - 1], nums[index]
            n -= 1
        else:
            index += 1

    # Use index as the size of the array with positive numbers
    for i in range(n):
        val = abs(nums[i])
        if val <= n:
            if nums[val - 1] > 0:
                nums[val - 1] = -nums[val - 1]

    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1
