def find_largest_prime_factor(number):
    """
    Returns the largest prime factor of the given number.
    If the number is less than or equal to 1, returns None.

    :param number: Integer, the number to find the largest prime factor of.
    :return: Integer, the largest prime factor, or None if number <= 1.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if number <= 1:
        return None

    largest_prime_factor = None
    factor = 2

    while number % factor == 0:
        largest_prime_factor = factor
        number //= factor

    factor = 3

    while factor * factor <= number:
        while number % factor == 0:
            largest_prime_factor = factor
            number //= factor
        factor += 2

    if number > 2:
        largest_prime_factor = number

    return largest_prime_factor
