def flatten_dict(nested_dict, parent_key='', sep='_'):
    """
    Flattens a nested dictionary or list into a flat dictionary with keys representing the path to each value.

    :param nested_dict: The nested dictionary or list to be flattened.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between path components.
    :return: A flat dictionary with path-based keys.
    """
    items = {}
    if isinstance(nested_dict, dict):
        for k, v in nested_dict.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.update(flatten_dict(v, new_key, sep=sep))
    elif isinstance(nested_dict, list):
        for i, v in enumerate(nested_dict):
            new_key = f"{parent_key}{sep}{i}"
            items.update(flatten_dict(v, new_key, sep=sep))
    else:
        items[parent_key] = nested_dict
    return items

