def fibonacci_memo(n: int, memo=None) -> int:
    """
    Computes the nth Fibonacci number using memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int: The nth Fibonacci number if n is non-negative, otherwise -1.
    """
    if memo is None:
        memo = {}
    if n < 0:
        return -1
    if n in memo:
        return memo[n]
    if n == 0 or n == 1:
        memo[n] = n
        return n
    else:
        memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
        return memo[n]
