def fibonacci(n):
    """
    Generate the first n numbers in the Fibonacci sequence using recursion.

    Parameters:
    n (int): The number of Fibonacci numbers to generate.

    Returns:
    list: A list containing the first n numbers in the Fibonacci sequence.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    def fib_recursive(k):
        if k <= 1:
            return k
        return fib_recursive(k - 1) + fib_recursive(k - 2)

    return [fib_recursive(i) for i in range(n)]
