import xml.etree.ElementTree as ET
import json

def generate_json_from_xml(xml_str):
    """
    Convert an XML string to a JSON object.

    Args:
    xml_str (str): A string containing XML data.

    Returns:
    str: A JSON string representing the equivalent hierarchical structure of the input XML.
    """
    def parse_element(element):
        parsed = {}
        for attr, value in element.attrib.items():
            parsed[f"@{attr}"] = value
        for child in list(element):
            child_result = parse_element(child)
            if child.tag not in parsed:
                parsed[child.tag] = child_result
            else:
                if not isinstance(parsed[child.tag], list):
                    parsed[child.tag] = [parsed[child.tag]]
                parsed[child.tag].append(child_result)
        if element.text and element.text.strip():
            text = element.text.strip()
            if list(parsed):
                parsed["#text"] = text
            else:
                parsed = text
        return parsed

    root = ET.fromstring(xml_str)
    return json.dumps(parse_element(root), indent=4)

