def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary, including support for lists.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string to use for recursion (used internally).
    :param sep: The separator to use between keys.
