def sum_of_primes(limit):
    """
    Calculate the sum of all prime numbers less than the given limit.

    :param limit: An integer representing the upper bound (exclusive) for prime numbers.
    :return: The sum of all prime numbers less than the limit.
    """
    if limit <= 2:
        return 0
    is_prime = [True] * limit
    is_prime[0] = is_prime[1] = False
    for num in range(2, int(limit ** 0.5) + 1):
        if is_prime[num]:
            for multiple in range(num*num, limit, num):
                is_prime[multiple] = False
    return sum(index for index, prime in enumerate(is_prime) if prime)
