import csv

def find_employee_with_highest_salary(file_path):
    """
    Reads a CSV file and prints the name and email address of the employee with the highest salary.

    Parameters:
    file_path (str): The path to the CSV file containing employee data.
    """
    highest_salary_employee = {'Name': None, 'Email': None, 'Salary': -1}

    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            for row in reader:
                if not row['Name'] or not row['Email'] or not row['Salary']:
                    continue

                try:
                    salary = float(row['Salary'])
                    if salary > highest_salary_employee['Salary']:
                        highest_salary_employee['Name'] = row['Name']
                        highest_salary_employee['Email'] = row['Email']
                        highest_salary_employee['Salary'] = salary
                except ValueError:
                    continue

    except FileNotFoundError:
        print(f"Error: The file at {file_path} was not found.")
        return
    except Exception as e:
        print(f"An error occurred: {str(e)}")
        return

    if highest_salary_employee['Name']:
        print(f"Employee with the highest salary: {highest_salary_employee['Name']}, {highest_salary_employee['Email']}")
    else:
        print("No valid employee data")

