def merge_inventories(dict1, dict2):
    """
    Recursively merges two dictionaries of inventories, keeping the item with the higher quantity
    or from dict1 if quantities are equal.

    Parameters:
    - dict1: Dictionary representing the inventory of the first store.
    - dict2: Dictionary representing the inventory of the second store.

    Returns:
    - merged_dict: A dictionary representing the merged inventory.
    """
    merged_dict = {}

    for key in set(dict1.keys()).union(set(dict2.keys())):
        if key in dict1 and key in dict2:
            if isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
                merged_dict[key] = merge_inventories(dict1[key], dict2[key])
            else:
                merged_dict[key] = max(dict1[key], dict2[key])
        elif key in dict1:
            merged_dict[key] = dict1[key]
        else:
            merged_dict[key] = dict2[key]

    return merged_dict
