def apply_operation(func, numbers):
    """
    Applies a given function to each integer in a nested list structure.

    Parameters:
    func (callable): A function that takes a single integer and returns an integer.
    numbers (list): A list of integers and nested lists of integers.

    Returns:
    list: A new list with the results of applying `func` to each integer.
    """
    def _apply_recursively(item):
        if isinstance(item, int):
            return func(item)
        elif isinstance(item, list):
            return [_apply_recursively(subitem) for subitem in item]
        else:
            raise ValueError("The list should contain only integers and nested lists of integers.")

