class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        Raises a ValueError if `data` is not a valid 2D list with consistent row lengths.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Input should be a 2D list with consistent row lengths.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __str__(self):
        """
        Returns a string representation of the matrix, with each row on a new line and elements separated by spaces.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def __add__(self, other):
        """
        Adds two matrices and returns a new Matrix object.
        Raises a ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts the second matrix from the first and returns a new Matrix object.
        Raises a ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices and returns a new Matrix object.
        Raises a ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)
