def merge_sorted_lists(list1, list2):
    """
    Merges two sorted lists into a single sorted list with unique elements.

    Parameters:
    list1 (List[int]): The first sorted list.
    list2 (List[int]): The second sorted list.

    Returns:
    List[int]: A sorted list containing all unique elements from both input lists.
    """
    result = []
    i, j = 0, 0
    len1, len2 = len(list1), len(list2)

    while i < len1 and j < len2:
        if list1[i] < list2[j]:
            if not result or result[-1] != list1[i]:
                result.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            if not result or result[-1] != list2[j]:
                result.append(list2[j])
            j += 1
        else:
            if not result or result[-1] != list1[i]:
                result.append(list1[i])
            i += 1
            j += 1

    # Append remaining elements from list1
    while i < len1:
        if not result or result[-1] != list1[i]:
            result.append(list1[i])
        i += 1

    # Append remaining elements from list2
    while j < len2:
        if not result or result[-1] != list2[j]:
