def prime_factor_exponent(n, divisor=2, factors=None):
    """
    Recursively finds the prime factors of n and their exponents.

    Parameters:
    n (int): The integer to factorize.
    divisor (int): The current divisor to check for factors.
    factors (dict): A dictionary to store the prime factors and their exponents.

    Returns:
    dict: A dictionary with prime factors as keys and their exponents as values.
    """
    if factors is None:
        factors = {}
    if n < 2:
        return factors
    if n % divisor == 0:
        if divisor in factors:
            factors[divisor] += 1
        else:
            factors[divisor] = 1
        return prime_factor_exponent(n // divisor, divisor, factors)
    else:
        next_divisor = divisor + 1 if divisor == 2 else divisor + 2
        if next_divisor * next_divisor > n:
            if n > 1:
                factors[n] = 1
            return factors
        return prime_factor_exponent(n, next_divisor, factors)
