class Matrix:
    def __init__(self, matrix):
        """
        Initializes the Matrix object with a 2D list.

        :param matrix: List of lists representing the matrix.
        """
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Adds two matrices and returns a new Matrix object.

        :param other: Another Matrix object to add.
        :return: New Matrix object representing the sum.
        :raises ValueError: If matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")

        result = [
            [self.matrix[i][j] + other.matrix[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts the second matrix from the first and returns a new Matrix object.

        :param other: Another Matrix object to subtract.
        :return: New Matrix object representing the difference.
        :raises ValueError: If matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")

        result = [
            [self.matrix[i][j] - other.matrix[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices and returns a new Matrix object.

        :param other: Another Matrix object to multiply.
        :return: New Matrix object representing the product.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")

        result = [
            [sum(self.matrix[i][k] * other.matrix[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.

        :return: String representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.matrix])
