def first_occurrence_binary_search(numbers, target, left=0, right=None):
    """
    Returns the index of the first occurrence of target in the sorted list numbers.
    If target is not found, returns -1.

    :param numbers: List[int] - A sorted list of integers.
    :param target: int - The target integer to find.
    :param left: int - The starting index for the search (default is 0).
    :param right: int - The ending index for the search (default is len(numbers) - 1).
    :return: int - The index of the first occurrence of target, or -1 if not found.
    """
    if right is None:
        right = len(numbers) - 1

    if left > right:
        return -1

    mid = (left + right) // 2

    if numbers[mid] > target:
        return first_occurrence_binary_search(numbers, target, left, mid - 1)
    elif numbers[mid] < target:
        return first_occurrence_binary_search(numbers, target, mid + 1, right)
    else:
        if mid == 0 or numbers[mid - 1] != target:
            return mid
        else:
            return first_occurrence_binary_search(numbers, target, left, mid - 1)
