def get_min_value(numbers: List[Union[int, float]], default: Union[int, float]) -> Union[int, float]:
    """
    Returns the minimum value from the list if it is not empty, otherwise returns the default value.

    :param numbers: List of integers or floats.
    :param default: Integer or float to return if the list is empty.
    :return: Minimum value from the list or the default value if the list is empty.
    """
    def is_empty(seq):
        try:
            seq[0]
            return False
        except IndexError:
            return True

    def find_min(seq):
        first, *rest = seq
        if not rest:
            return first
        else:
            rest_min = find_min(rest)
            return first if first < rest_min else rest_min

    if is_empty(numbers):
        return default
    else:
        return find_min(numbers)
