        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Adds two matrices and returns the result as a new Matrix object.

        :param other: Another Matrix object to be added to the current matrix.
        :return: A new Matrix object representing the sum of the two matrices.
