            raise ValueError("Matrices must have the same dimensions for addition")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts one matrix from another and returns the result as a new Matrix object.

        :param other: Another Matrix object to be subtracted from the current matrix.
        :return: A new Matrix object representing the difference of the two matrices.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices and returns the result as a new Matrix object.

        :param other: Another Matrix object to be multiplied with the current matrix.
        :return: A new Matrix object representing the product of the two matrices.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")

        result = [
            [
                sum(self.data[i][k] * other.data[k][j] for k in range(self.cols))
                for j in range(other.cols)
            ]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
