def length_of_longest_increasing_subsequence(nums):
    """
    Calculate the length of the longest increasing subsequence in a given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    tails = []

    for num in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

