class MinHeap:
    def __init__(self):
        """Initialize an empty min-heap."""
        self.heap = []

    def parent(self, index):
        """Return the index of the parent of the element at the given index."""
        return (index - 1) // 2

    def left_child(self, index):
        """Return the index of the left child of the element at the given index."""
        return 2 * index + 1

    def right_child(self, index):
        """Return the index of the right child of the element at the given index."""
        return 2 * index + 2

    def insert(self, element):
        """Insert an element into the heap."""
        self.heap.append(element)
        self._heapify_up(len(self.heap) - 1)

    def _heapify_up(self, index):
        """Restore the heap property by moving the element at the given index up."""
        while index != 0 and self.heap[self.parent(index)] > self.heap[index]:
            self.heap[index], self.heap[self.parent(index)] = self.heap[self.parent(index)], self.heap[index]
            index = self.parent(index)

    def extract_min(self):
        """Remove and return the minimum element from the heap."""
        if not self.heap:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()

        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._heapify_down(0)
        return root

    def _heapify_down(self, index):
        """Restore the heap property by moving the element at the given index down."""
        smallest = index
        left = self.left_child(index)
        right = self.right_child(index)

        if left < len(self.heap) and self.heap[left] < self.heap[smallest]:
            smallest = left
        if right < len(self.heap) and self.heap[right] < self.heap[smallest]:
            smallest = right
        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self._heapify_down(smallest)

    def peek(self):
        """Return the minimum element from the heap without removing it."""
        if not self.heap:
            return None
        return self.heap[0]
