def has_cycle(graph):
    """
    Determines if the given directed graph contains a cycle.

    :param graph: A dictionary representing the directed graph, where keys are nodes
                  and values are lists of adjacent nodes.
    :return: True if the graph contains a cycle, False otherwise.
    """
    def is_cyclic_util(node, visited, rec_stack):
        visited[node] = True
        rec_stack[node] = True

        for neighbour in graph[node]:
            if not visited[neighbour]:
                if is_cyclic_util(neighbour, visited, rec_stack):
                    return True
            elif rec_stack[neighbour]:
                return True

        rec_stack[node] = False
        return False

    visited = {node: False for node in graph}
    rec_stack = {node: False for node in graph}

    for node in graph:
        if not visited[node]:
            if is_cyclic_util(node, visited, rec_stack):
                return True
    return False

