# Stack implementation using a Python list
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        """Add an item to the top of the stack."""
        self.items.append(item)

    def pop(self):
        """Remove and return the top item of the stack. Return None if the stack is empty."""
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self):
        """Return the top item of the stack without removing it. Return None if the stack is empty."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def is_empty(self):
        """Return True if the stack is empty, otherwise False."""
        return len(self.items) == 0

    def size(self):
        """Return the number of items in the stack."""
        return len(self.items)


# Queue implementation using a Python list
class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        """Add an item to the end of the queue."""
        self.items.append(item)

    def dequeue(self):
        """Remove and return the front item of the queue. Return None if the queue is empty."""
        if not self.is_empty():
            return self.items.pop(0)
        return None

    def front(self):
        """Return the front item of the queue without removing it. Return None if the queue is empty."""
        if not self.is_empty():
            return self.items[0]
        return None

    def is_empty(self):
        """Return True if the queue is empty, otherwise False."""
        return len(self.items) == 0

    def size(self):
        """Return the number of items in the queue."""
        return len(self.items)


