class HashNode:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None

class HashTable:
    def __init__(self, capacity=10):
        self.capacity = capacity
        self.size = 0
        self.table = [None] * self.capacity

    def _hash_function(self, key):
        hash_sum = 0
        for char in key:
            hash_sum += ord(char)
        return hash_sum % self.capacity

    def insert(self, key, value):
        """
        Inserts a key-value pair into the hash table. If the key already exists, updates the value.
        """
        index = self._hash_function(key)
        new_node = HashNode(key, value)
        node = self.table[index]
        if node is None:
            self.table[index] = new_node
            self.size += 1
        else:
            while node.next is not None:
                if node.key == key:
                    node.value = value
                    return
                node = node.next
            if node.key == key:
                node.value = value
            else:
                node.next = new_node
                self.size += 1

    def search(self, key):
        """
        Returns the value associated with the key if it exists, otherwise returns None.
        """
        index = self._hash_function(key)
        node = self.table[index]
        while node is not None:
            if node.key == key:
                return node.value
            node = node.next
        return None

    def delete(self, key):
        """
        Removes the key-value pair from the hash table if the key exists.
        Returns True if the key was found and deleted, otherwise returns False.
        """
        index = self._hash_function(key)
        node = self.table[index]
        prev = None
        while node is not None:
            if node.key == key:
                if prev is not None:
                    prev.next = node.next
                else:
                    self.table[index] = node.next
                self.size -= 1
                return True
            prev = node
            node = node.next
        return False

    def __repr__(self):
        result = []
        for index, node in enumerate(self.table):
            temp = []
            while node is not None:
                temp.append((node.key, node.value))
                node = node.next
            result.append(str(index) + ": " + str(temp))
        return "\n".join(result)
