import re

def extract_urls(data):
    """
    Extracts all valid URLs from a nested data structure.

    Args:
        data (dict, list, tuple): The nested data structure containing potential URLs.

    Returns:
        set: A set of unique valid URLs.
    """
    valid_url_regex = re.compile(
        r'https?://(?:www\.)?[a-zA-Z0-9-]+\.[a-zA-Z]{2,}'  # Simplified URL regex
    )

    urls = set()

    def _extract_from_dict(d):
        for k, v in d.items():
            if isinstance(v, dict):
                _extract_from_dict(v)
            elif isinstance(v, (list, tuple)):
                _extract_from_list(v)
            elif isinstance(v, str):
                if valid_url_regex.match(v):
                    urls.add(v)

    def _extract_from_list(lst):
        for item in lst:
            if isinstance(item, dict):
                _extract_from_dict(item)
            elif isinstance(item, (list, tuple)):
                _extract_from_list(item)
            elif isinstance(item, str):
                if valid_url_regex.match(item):
                    urls.add(item)

    if isinstance(data, dict):
        _extract_from_dict(data)
    elif isinstance(data, (list, tuple)):
        _extract_from_list(data)

    return urls
