def find_max_prime_factor(n):
    """
    Finds the largest prime factor of a given positive integer n.

    Parameters:
    n (int): A positive integer.

    Returns:
    int or None: The largest prime factor of n, or None if n is less than or equal to 1.
    """
    if n <= 1:
        return None

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    while n % 2 == 0:
        max_prime = 2
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            max_prime = i
            n //= i

    if n > 2:
        max_prime = n

    return max_prime
