def flatten_dict(d, parent_key='', sep='/'):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Parameters:
    - d: The dictionary to flatten.
    - parent_key: The base key string for recursion (used internally).
    - sep: The separator to use between keys.

    Returns:
    - A new flattened dictionary.
    """
    items = {}
    if isinstance(d, dict):
        for k in sorted(d.keys()):
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.update(flatten_dict(d[k], new_key, sep=sep))
    elif isinstance(d, list):
        for i, item in enumerate(d):
            new_key = f"{parent_key}{sep}{i}"
            items.update(flatten_dict(item, new_key, sep=sep))
    else:
        items[parent_key] = d
    return items

