class SimpleCache:
    def __init__(self):
        """Initializes an empty cache."""
        self.cache = {}

    def put(self, key, value):
        """Stores the value for a given key in the cache. Updates the value if the key already exists."""
        self.cache[key] = value

    def get(self, key):
        """Retrieves the value for a given key from the cache. Returns None if the key does not exist."""
        return self.cache.get(key, None)

    def remove(self, key):
        """Removes the value for a given key from the cache. Does nothing if the key does not exist."""
        if key in self.cache:
            del self.cache[key]

    def clear(self):
        """Clears all values from the cache."""
        self.cache.clear()

    def size(self):
        """Returns the number of items currently stored in the cache."""
        return len(self.cache)

