import random

def partition(arr, low, high):
    """
    Partitions the array around a pivot element and returns the index of the pivot.
    """
    pivot_index = random.randint(low, high)
    pivot_value = arr[pivot_index]
    arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
    store_index = low
    for i in range(low, high):
        if arr[i] < pivot_value:
            arr[i], arr[store_index] = arr[store_index], arr[i]
            store_index += 1
    arr[store_index], arr[high] = arr[high], arr[store_index]
    return store_index

def quickselect(arr, low, high, k):
    """
    Selects the k-th smallest element in the array using the Quickselect algorithm.
    """
    if low == high:
        return arr[low]

    pivot_index = partition(arr, low, high)

    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, low, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, high, k)

def find_kth_smallest(numbers, k):
    """
    Returns the k-th smallest element in the array without modifying the original array.
    """
    if not numbers or k <= 0 or k > len(numbers):
        raise ValueError("Invalid input")

    numbers_copy = numbers[:]
    return quickselect(numbers_copy, 0, len(numbers_copy) - 1, k - 1)

# Example usage:
