import math

def generate_primes(n):
    """
    Generate the first n prime numbers using the Sieve of Eratosthenes algorithm.

    Parameters:
    n (int): The number of prime numbers to generate.

    Returns:
    list: A list containing the first n prime numbers.
    """
    if n < 1:
        return []
    elif n == 1:
        return [2]

    if n < 6:
        limit = 15
    else:
        limit = int(n * math.log(n) + n * math.log(math.log(n)))

    is_prime = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1

    primes = []
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
        if len(primes) == n:
            break

    return primes

