def process_arguments(args):
    """
    Processes a list of command line arguments, distinguishing between parameter files and global parameters.

    Args:
    args (list of str): The list of command line arguments.

    Returns:
    tuple: A tuple containing the parameter file (str) and the dictionary of global parameters (dict).

    Raises:
    ValueError: If the number of parameter files is not exactly one, or if a global parameter key is invalid,
                or if a global parameter value cannot be converted to a float.
    """
    parameter_files = []
    global_params = {}
    predefined_keys = {"learning_rate", "batch_size", "epochs"}

    for arg in args:
        if ':' in arg:
            key, value = arg.split(':', 1)
            if key not in predefined_keys:
                raise ValueError(f"Invalid global parameter key: {key}. Must be one of {predefined_keys}.")
            try:
                global_params[key] = float(value)
            except ValueError:
                raise ValueError(f"Global parameter value for {key} must be a float.")
        else:
            parameter_files.append(arg)

    if len(parameter_files) != 1:
        raise ValueError("Exactly one parameter file must be provided.")

    parameter_file = parameter_files[0]

    return parameter_file, global_params
