def convert_to_json(data):
    """
    Serializes a given Python dictionary into a JSON-formatted string.

    :param data: A dictionary that may contain nested dictionaries and lists, with values of types: string, integer, float, boolean, None, list, or dictionary.
    :return: A string representing the JSON-formatted serialization of the input dictionary.
    """
    def convert(element):
        if isinstance(element, dict):
            items = [f'"{k}": {convert(v)}' for k, v in element.items()]
            return '{' + ', '.join(items) + '}'
        elif isinstance(element, list):
            items = [convert(item) for item in element]
            return '[' + ', '.join(items) + ']'
        elif isinstance(element, str):
            return f'"{element}"'
        elif isinstance(element, bool):
            return 'true' if element else 'false'
        elif element is None:
            return 'null'
        else:  # handle int and float
            return str(element)

    return convert(data)
