def calculate_fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    The Fibonacci sequence is a series of numbers where each number is the sum of the two preceding ones, starting with 0 and 1.

    Parameters:
    n (int): The position in the Fibonacci sequence to calculate. The first position (n=0) corresponds to the first Fibonacci number, which is 0.

    Returns:
    int: The nth Fibonacci number if n is non-negative, otherwise returns -1 indicating invalid input.
    """
    if n < 0:
        return -1
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return calculate_fibonacci(n - 1) + calculate_fibonacci(n - 2)
