        # Check if mid is the peak
        if (mid == 0 or buildings[mid - 1] <= buildings[mid]) and \
           (mid == n - 1 or buildings[mid + 1] <= buildings[mid]):
            return buildings[mid]

        # If the left neighbor is greater, then the peak must be in the left half
        if mid > 0 and buildings[mid - 1] > buildings[mid]:
            return find_peak_util(low, mid - 1, n)

        # If the right neighbor is greater, then the peak must be in the right half
        return find_peak_util(mid + 1, high, n)

    return find_peak_util(0, n - 1, n)
