    Finds and returns the longest string in a list. If there are multiple strings
    with the same maximum length, returns the first one encountered. Raises a
    TypeError if the input is not a list, and a ValueError if the list contains
    non-string elements.

    :param strings: List of strings to evaluate.
    :return: The longest string in the list, or None if the list is empty.
    :raises TypeError: If the input is not a list.
    :raises ValueError: If the list contains non-string elements.
    """
    if not isinstance(strings, list):
        raise TypeError("Input should be a list of strings.")

    if not all(isinstance(s, str) for s in strings):
        raise ValueError("All elements in the list should be strings.")

    if not strings:
        return None  # Return None if the list is empty

    longest_string = strings[0]
    for string in strings:
        if len(string) > len(longest_string):
            longest_string = string

    return longest_string

