class Graph:
    def __init__(self):
        """Initialize an empty dictionary to store the graph's adjacency list."""
        self.graph = {}

    def add_vertex(self, vertex):
        """Add a new vertex to the graph if it does not already exist."""
        if vertex not in self.graph:
            self.graph[vertex] = set()

    def add_edge(self, vertex1, vertex2):
        """Add an edge between two vertices. This method also adds vertices to the graph if they do not exist."""
        self.add_vertex(vertex1)
        self.add_vertex(vertex2)
        self.graph[vertex1].add(vertex2)
        self.graph[vertex2].add(vertex1)

    def remove_vertex(self, vertex):
        """Remove a vertex from the graph, including all the edges that are connected to it."""
        if vertex in self.graph:
            for connected_vertex in self.graph[vertex]:
                self.graph[connected_vertex].remove(vertex)
            self.graph.pop(vertex)

    def remove_edge(self, vertex1, vertex2):
        """Remove an edge between two vertices if both exist in the graph."""
        if vertex1 in self.graph and vertex2 in self.graph[vertex1]:
            self.graph[vertex1].remove(vertex2)
            self.graph[vertex2].remove(vertex1)

    def get_all_vertices(self):
        """Return a list of all vertices in the graph."""
        return list(self.graph.keys())

    def get_all_edges(self):
        """Return a set of all unique edges in the graph. Each edge is represented as a tuple (vertex1, vertex2)."""
        edges = set()
        for vertex in self.graph:
            for connected_vertex in self.graph[vertex]:
                edges.add((min(vertex, connected_vertex), max(vertex, connected_vertex)))
        return edges

    def vertex_exists(self, vertex):
        """Check if a specific vertex exists in the graph."""
        return vertex in self.graph.keys()

    def edge_exists(self, vertex1, vertex2):
        """Check if an edge exists between two specific vertices."""
        return vertex1 in self.graph and vertex2 in self.graph[vertex1]
