def prime_numbers_below(n):
    """
    Generator function that yields all prime numbers less than a given integer n.

    :param n: An integer representing the upper limit (exclusive) for prime numbers.
    :yield: The next prime number less than n.
    """
    def is_prime(num):
        """
        Helper function to determine if a number is prime.

        :param num: An integer to check for primality.
        :return: True if num is prime, False otherwise.
        """
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
