import math

class Point2D:
    def __init__(self, x=0.0, y=0.0):
        """Initialize a point with x and y coordinates."""
        self.x = x
        self.y = y

    def distance_to(self, other):
        """Calculate the Euclidean distance to another Point2D instance."""
        if not isinstance(other, Point2D):
            raise ValueError("The argument must be an instance of Point2D")
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def midpoint_with(self, other):
        """Calculate the midpoint between this point and another Point2D instance."""
        if not isinstance(other, Point2D):
            raise ValueError("The argument must be an instance of Point2D")
        mid_x = (self.x + other.x) / 2
        mid_y = (self.y + other.y) / 2
        return Point2D(mid_x, mid_y)

    def __repr__(self):
        """Return a string representation of the Point2D instance."""
        return f"Point2D({self.x}, {self.y})"
