class Matrix:
    def __init__(self, rows=1, cols=1, data=None):
        """
        Initializes a matrix with the given number of rows and columns.
        If data is provided, it initializes the matrix with the given data.
        Otherwise, it initializes a matrix with zeros.
        """
        if data:
            self.data = data
            self.rows = len(data)
            self.cols = len(data[0]) if self.rows > 0 else 0
        else:
            self.rows = rows
            self.cols = cols
            self.data = [[0] * cols for _ in range(rows)]

    def __str__(self):
        """
        Returns a string representation of the matrix.
        Each row is on a new line and elements in a row are separated by a tab.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])

    def __add__(self, other):
        """
        Implements matrix addition.
        Both matrices must have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")

        result = Matrix(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                result.data[i][j] = self.data[i][j] + other.data[i][j]
        return result

    def __mul__(self, other):
        """
        Implements matrix multiplication.
        The number of columns in the first matrix must equal the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must equal the number of rows in the second matrix for multiplication.")

        result = Matrix(self.rows, other.cols)
        for i in range(self.rows):
            for j in range(other.cols):
                result.data[i][j] = sum(self.data[i][k] * other.data[k][j] for k in range(self.cols))
        return result

    def transpose(self):
        """
        Returns a new matrix that is the transpose of the original matrix.
        """
        result = Matrix(self.cols, self.rows)
        for i in range(self.rows):
            for j in range(self.cols):
                result.data[j][i] = self.data[i][j]
        return result
