        """Add a directed edge from node1 to node2. Add nodes if they do not exist."""
        if node1 not in self.graph:
            self.add_node(node1)
        if node2 not in self.graph:
            self.add_node(node2)
        if node2 not in self.graph[node1]:
            self.graph[node1].append(node2)

    def get_nodes(self):
        """Return a list of all nodes in the graph."""
        return list(self.graph.keys())

    def get_edges(self):
        """Return a list of all directed edges in the graph as tuples."""
        edges = []
        for node, neighbors in self.graph.items():
            for neighbor in neighbors:
                edges.append((node, neighbor))
        return edges

    def node_exists(self, node):
        """Check if a specific node exists in the graph."""
        return node in self.graph

    def edge_exists(self, node1, node2):
        """Check if a directed edge exists from node1 to node2."""
        return node2 in self.graph.get(node1, [])
