    _instance = None

    def __new__(cls):
        """Ensure only one instance of Logger is created."""
        if cls._instance is None:
            with cls._instance_lock:
                if cls._instance is None:
                    cls._instance = super(Logger, cls).__new__(cls)
                    cls._instance.logged_messages = []
        return cls._instance

    def log_message(self, message):
        """Append a message to the list of logged messages in a thread-safe manner."""
        with self._instance_lock:
            self.logged_messages.append(message)

    def get_logged_messages(self):
        """Return a copy of the list of logged messages in a thread-safe manner."""
        with self._instance_lock:
            return self.logged_messages.copy()
