def prime_generator(n):
    """
    A generator function that yields all prime numbers less than or equal to n.

    Parameters:
    n (int): The upper limit up to which prime numbers are yielded.

    Yields:
    int: A prime number less than or equal to n.
    """
    if n < 2:
        return

    sieve = [True] * (n + 1)
    for p in range(2, int(n**0.5) + 1):
        if sieve[p]:
            for multiple in range(p * p, n + 1, p):
                sieve[multiple] = False

    for prime in range(2, n + 1):
        if sieve[prime]:
            yield prime
