def prime_generator(n):
    """
    Return a generator object that yields all prime numbers less than a given number n.

    :param n: An integer representing the upper limit (exclusive) for prime numbers.
    :yield: Prime numbers less than n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        elif num <= 3:
            return True
        elif num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    for num in range(2, n):
        if is_prime(num):
            yield num
