def find_longest_common_substring(strings):
    """
    Finds the longest common substring among all strings in the list.

    :param strings: List of strings to find the common substring in.
    :return: The longest common substring or an empty string if none exists.
    """
    if not strings:
        return ""

    def is_common_substring(sub):
        return all(sub in s for s in strings)

    longest_common = ""
    first_string = strings[0]

    for i in range(len(first_string)):
        for j in range(i + 1, len(first_string) + 1):
            candidate = first_string[i:j]
            if len(candidate) > len(longest_common) and is_common_substring(candidate):
                longest_common = candidate

