def convert_to_string(value):
    """
    Converts an input value of any type to a string according to specific rules.

    Parameters:
    value: The input value to be converted.

    Returns:
    A string representation of the input value or None if the input is None or an empty string.
    """
    if value is None or value == "":
        return None

    if isinstance(value, list):
        if not value:
            return None
        elif len(value) == 1:
            return str(value[0])
        else:
            all_except_last = ', '.join(str(item) for item in value[:-1])
            return f"{all_except_last} and {value[-1]}"

    if isinstance(value, dict):
        if not value:
            return None
        sorted_items = sorted(value.items(), key=lambda item: item[0], reverse=True)
        return '; '.join(f"{key}={value}" for key, value in sorted_items)

    return str(value)
