    :param d: Nested dictionary representing processes and their CPU usage percentiles.
    :return: List of tuples with process names and their most recent CPU usage percentile.
    """
    def extract_cpu_usage(process_data):
        if isinstance(process_data, dict):
            if 'cpu_usage_percentile' in process_data:
                return process_data['cpu_usage_percentile'][0]
            else:
                for key, value in process_data.items():
                    result = extract_cpu_usage(value)
                    if result is not None:
                        return result
        return None

    process_usage = []
    for process_name, process_data in d.items():
        cpu_usage = extract_cpu_usage(process_data)
        if cpu_usage is not None:
            process_usage.append((process_name, cpu_usage))

    process_usage.sort(key=lambda x: x[1], reverse=True)

    return process_usage[:n]
