def min_removals_to_balance_parentheses(s: str) -> int:
    """
    Returns the minimum number of characters to remove to make the input string of parentheses balanced.

    :param s: A string consisting of '(' and ')'.
    :return: An integer representing the minimum number of characters to remove.
    """
    stack = 0
    result = 0

    for c in s:
        if c == '(':
            stack += 1
        elif c == ')':
            if stack == 0:
                result += 1
            else:
                stack -= 1

