def prime_count(n):
    """
    Returns the count of all prime numbers less than n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for counting prime numbers.
    :return: An integer count of prime numbers less than n.
    """
    if n <= 2:
        return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return sum(is_prime)
