import string

def count_words(input_file, output_file, stop_words):
    """
    Reads a text file, counts the frequency of each word ignoring stop words,
    and writes the frequencies to a new file.

    :param input_file: str, path to the input text file
    :param output_file: str, path to the output text file
    :param stop_words: list, list of stop words to ignore
    """
    word_count = {}

    try:
        with open(input_file, 'r') as file:
            for line in file:
                line = line.translate(str.maketrans('', '', string.punctuation)).lower()
                words = line.split()
                for word in words:
                    if word not in stop_words:
                        word_count[word] = word_count.get(word, 0) + 1

        with open(output_file, 'w') as file:
            for word, count in sorted(word_count.items(), key=lambda item: item[1], reverse=True):
                file.write(f"{word}: {count}\n")

    except FileNotFoundError:
        print(f"Error: The file {input_file} was not found.")
    except IOError:
        print("An error occurred while reading or writing files.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

