def is_valid(s: str) -> bool:
    """
    Determines if the input string s containing only '(', ')', '{', '}', '[' and ']' is valid.
    A string is valid if open brackets are closed by the same type of brackets in the correct order.

    :param s: The input string containing brackets.
    :return: True if the string is valid, False otherwise.
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
```

