def find_min_max(numbers):
    """
    Returns a tuple containing the minimum and maximum values from the list.
    If the list is empty, returns None.

    :param numbers: List of integers
    :return: Tuple (min, max) or None if the list is empty
    """
    if not numbers:
        return None

    min_val = max_val = numbers[0]
    for i in range(1, len(numbers), 2):
        if i + 1 < len(numbers):
            if numbers[i] > numbers[i + 1]:
                local_max, local_min = numbers[i], numbers[i + 1]
            else:
                local_max, local_min = numbers[i + 1], numbers[i]
        else:
            local_max = local_min = numbers[i]

        if local_max > max_val:
            max_val = local_max
        if local_min < min_val:
            min_val = local_min

    return min_val, max_val
