        elif title in self.borrowed_books:
            print(f"Book '{title}' is currently borrowed and cannot be removed.")
        else:
            print(f"Book '{title}' is not in the library.")

    def borrow_book(self, title, borrower_name):
        """Borrow a book from the library if it is available."""
        if title in self.available_books:
