        """Remove and return the item from the front of the queue. Return None if the queue is empty."""
        if not self.is_empty():
            return self.items.pop(0)
        return None

    def peek(self):
        """Return the item at the front of the queue without removing it. Return None if the queue is empty."""
        if not self.is_empty():
            return self.items[0]
        return None

    def is_empty(self):
        """Check if the queue is empty. Return True if it is empty, otherwise False."""
        return len(self.items) == 0
