class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        """Inserts a value into the BST."""
        if not self.root:
            self.root = TreeNode(val)
        else:
            self._insert(self.root, val)

    def _insert(self, node, val):
        """Helper method to insert a value into the BST recursively."""
        if val < node.val:
            if not node.left:
                node.left = TreeNode(val)
            else:
                self._insert(node.left, val)
        else:
            if not node.right:
                node.right = TreeNode(val)
            else:
                self._insert(node.right, val)

    def find_closest(self, target):
        """Finds the value in the BST closest to the target."""
        return self._find_closest(self.root, target, float('inf'))

    def _find_closest(self, node, target, closest):
        """Helper method to find the closest value recursively."""
        if not node:
            return closest
        if abs(target - node.val) < abs(target - closest):
            closest = node.val
        elif abs(target - node.val) == abs(target - closest):
            closest = min(closest, node.val)
        if target < node.val:
            return self._find_closest(node.left, target, closest)
        elif target > node.val:
            return self._find_closest(node.right, target, closest)
        else:
            return closest

def find_closest_node(nums, target):
    """Constructs a BST from nums and finds the node value closest to target."""
    bst = BST()
    for num in nums:
        bst.insert(num)
    return bst.find_closest(target)
```

