def merge_inventory(dict1, dict2):
    """
    Merges the inventories of two stores represented by dictionaries.

    Parameters:
    dict1 (dict): The inventory of the first store.
    dict2 (dict): The inventory of the second store.

    Returns:
    dict: A merged inventory dictionary with keys sorted alphabetically.
    """
    def merge(d1, d2):
        all_keys = sorted(set(d1.keys()).union(d2.keys()))
        merged_dict = {}
        for key in all_keys:
            v1 = d1.get(key, 0)
            v2 = d2.get(key, 0)
            if isinstance(v1, dict) and isinstance(v2, dict):
                merged_dict[key] = merge(v1, v2)
            else:
                merged_dict[key] = v1 + v2 if isinstance(v1, (int, float)) and isinstance(v2, (int, float)) else v1 or v2
        return merged_dict

    return merge(dict1, dict2)
