def process_data(dataDict):
    """
    Recursively process a dictionary or list, rounding all float values to two decimal places.

    :param dataDict: A dictionary or a list containing nested dictionaries, lists, and float values
    :return: A new dictionary or list with all float values rounded to two decimal places
    """
    if isinstance(dataDict, dict):
        return {key: process_data(value) for key, value in dataDict.items()}
    elif isinstance(dataDict, list):
        return [process_data(item) for item in dataDict]
    elif isinstance(dataDict, float):
        return round(dataDict, 2)
    else:
        return dataDict

