def merge_jsons(file_paths):
    """
    Merge JSON objects from a list of file paths according to specified rules.

    :param file_paths: List of file paths containing JSON objects.
    :return: A string representing the merged JSON object, or an error message.
    """
    merged_json = {}

    for file_path in file_paths:
        if not os.path.exists(file_path):
            return f"Error: File '{file_path}' does not exist."

        try:
            with open(file_path, 'r') as file:
                current_json = json.load(file)
        except json.JSONDecodeError:
            return f"Error: File '{file_path}' is not a valid JSON file."

        for key, value in current_json.items():
            if key in merged_json:
                if is_numeric(value) and is_numeric(merged_json[key]):
                    merged_json[key] += value
                else:
                    merged_json[key] = value
            else:
                merged_json[key] = value

    return json.dumps(merged_json)
