        self.value = value
        self.left = left
        self.right = right

def inorder_traversal(root):
    """
    Perform an in-order traversal of a binary search tree (BST).

    :param root: TreeNode, the root of the BST
    :return: List[int], the in-order traversal of the BST
    """
    def traverse(node):
        if node is None:
            return []
        return traverse(node.left) + [node.value] + traverse(node.right)

    return traverse(root)
