def compress_whitespace(text):
    """
    Compresses the whitespace in the input string `text` such that there is only one space between words
    and no leading or trailing whitespace.

    :param text: The input string containing characters and whitespace.
    :return: A string with compressed whitespace.
    """
    result = []
    in_whitespace = False

    for i in range(len(text)):
        char = text[i]

        if char == ' ':
            if not in_whitespace:
                in_whitespace = True
                result.append(' ')
        else:
            in_whitespace = False
            result.append(char)

    if result and result[0] == ' ':
        result.pop(0)
    if result and result[-1] == ' ':
        result.pop()

    return ''.join(result)
