def find_target(nums, target):
    """
    Returns the index of the first occurrence of target in the sorted list nums.
    If target is not found, returns -1.

    :param nums: List[int] - A sorted list of integers.
    :param target: int - The target integer to find.
    :return: int - The index of the first occurrence of target, or -1 if not found.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if nums[mid] == target:
            if mid == 0 or nums[mid - 1] != target:
                return mid
            else:
                right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1
```

