def is_balanced_parentheses(expression):
    """
    Determines if the given string of parentheses is balanced.

    :param expression: A string consisting of '(', ')', '{', '}', '[', and ']'.
    :return: True if the string is balanced, False otherwise.
    """
    matching_parentheses = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in expression:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            stack.pop()

    return not stack
