class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.key:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def lookup(self, key):
        """Check if a key exists in the BST."""
        return self._lookup(self.root, key)

    def _lookup(self, node, key):
        if node is None:
            return False
        elif key == node.key:
            return True
        elif key < node.key:
            return self._lookup(node.left, key)
        else:
            return self._lookup(node.right, key)

    def find_min(self, node):
        """Find the node with the minimum key in the subtree rooted at node."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def delete(self, key):
        """Delete a key from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return node
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            temp = self.find_min(node.right)

            node.key = temp.key

            node.right = self._delete(node.right, temp.key)

        return node

