class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, node, key):
        """Helper method to insert a new key into the BST recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursively(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursively(node.right, key)

    def in_order_traversal(self):
        """Return the elements of the BST in sorted order using in-order traversal."""
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        """Helper method to perform in-order traversal recursively."""
        result = []
        if node:
            result = self._in_order_traversal_recursively(node.left)
            result.append(node.val)
            result = result + self._in_order_traversal_recursively(node.right)
        return result

    def find_min(self):
        """Return the minimum value in the BST."""
        current_node = self.root
        while current_node and current_node.left:
            current_node = current_node.left
        return current_node.val if current_node else None
